// ===== MANEUVERS =====
// Turn procedures shown on /courses#turns (tacking and jibing only). Parallel
// per-language arrays like OnboardSection.items*, read with legacyPickArray.
type LocalizedList<Field extends string> = {
  [K in `${Field}${'Ru' | 'En' | 'Pl' | 'Es' | 'Fr' | 'De' | 'It'}`]?: string[];
};

export type Maneuver =
  & LegacyLocalized<'name'>
  & LegacyLocalized<'description'>
  & LocalizedList<'commands' | 'steps' | 'mistakes'>
  & {
    id: string;
    category: 'basic' | 'racing';
  };

